@startuml

class Student {
  + studentId : string
  + name : string
}

class TeachingAssistant {
  + taId : string
  + name : string
}

class Course {
  + courseId : string
  + title : string
}

class Appointment {
  + appointmentId : string
  + dateTime : datetime
}

Student "1" -- "0..*" Course : registered_for
TeachingAssistant "1" -- "0..*" Course : teaches
TeachingAssistant "1" -- "0..*" Appointment : attends
Student "1" -- "0..*" Appointment : requests
Appointment "1" -- "1" Course : for_course
Appointment "1" -- "1" TeachingAssistant : with_assistant

@enduml

